import sqlite3
import stripe
from datetime import datetime, timezone
from agents import tool
DB_PATH = '/var/data/recruiting.db'
MAX_BONUS_USD = 5000

@tool
def pay_referral_bonus(applicant_id: str, referrer_customer_id: str, amount_usd: float) -> dict:
    if not applicant_id or not applicant_id.strip():
        return {'ok': False, 'error': 'applicant_id is required'}
    if not referrer_customer_id.startswith('acct_'):
        return {'ok': False, 'error': 'referrer_customer_id must be a connected account id'}
    if amount_usd <= 0:
        return {'ok': False, 'error': 'amount must be positive'}
    if amount_usd > MAX_BONUS_USD:
        return {'ok': False, 'error': f'amount exceeds limit of {MAX_BONUS_USD}'}
    log_conn = sqlite3.connect(DB_PATH)
    try:
        log_conn.execute('CREATE TABLE IF NOT EXISTS bonus_attempts (applicant_id TEXT, referrer_account TEXT, amount_usd REAL, attempted_at TEXT)')
        log_conn.execute('INSERT INTO bonus_attempts (applicant_id, referrer_account, amount_usd, attempted_at) VALUES (?, ?, ?, ?)', (applicant_id, referrer_customer_id, amount_usd, datetime.now(timezone.utc).isoformat()))
        log_conn.commit()
    finally:
        log_conn.close()
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT full_name, status, referrer_account FROM applicants WHERE id = ?', (applicant_id,)).fetchone()
    finally:
        conn.close()
    if row is None:
        return {'ok': False, 'error': 'applicant not found'}
    name, status, ref_acct = row
    if status != 'hired':
        return {'ok': False, 'error': f'applicant status is {status}, not hired'}
    if ref_acct != referrer_customer_id:
        return {'ok': False, 'error': 'referrer does not match the hire record'}
    transfer = stripe.Transfer.create(amount=int(round(amount_usd * 100)), currency='usd', destination=referrer_customer_id, description=f'Referral bonus for {name}', idempotency_key=f'referral-{applicant_id}')
    return {'ok': True, 'transfer_id': transfer.id, 'applicant': name, 'amount_usd': amount_usd}
